(1, 1, 'en', 'Faculty of Engineering', 'Engineering', 'Power engineering, architecture, infrastructure design, mechanics, and textile materials science.', NULL, 'Faculty of Engineering - BSTU', 'Power engineering, architecture, infrastructure design, mechanics, and textile materials science.', '2026-07-16 00:25:34', '2026-07-16 00:25:34'),
(2, 1, 'uz', 'Muhandislik fakulteti', 'Muhandislik fakulteti', 'Elektr energetikasi, me\'morchilik, qurilish muhandisligi, yengil sanoat dizayni va mexanika.', NULL, 'Muhandislik fakulteti - BSTU', 'Elektr energetikasi, me\'morchilik, qurilish muhandisligi, yengil sanoat dizayni va mexanika.', '2026-07-16 00:25:34', '2026-07-16 00:25:34'),
(3, 1, 'ru', 'Инженерный факультет', 'Инженерный факультет', 'Электроэнергетика, архитектура, строительная инженерия, дизайн легкой промышленности и механика.', NULL, 'Инженерный факультет - BSTU', 'Электроэнергетика, архитектура, строительная инженерия, дизайн легкой промышленности и механика.', '2026-07-16 00:25:34', '2026-07-16 00:25:34'),
(4, 1, 'ar', 'كلية الهندسة', 'كلية الهندسة', 'هندسة الطاقة، الهندسة المعمارية، الهندسة المدنية، وتصميم الصناعات الخفيفة والمنسوجات والميكانيكا.', NULL, 'كلية الهندسة - BSTU', 'هندسة الطاقة، الهندسة المعمارية، الهندسة المدنية، وتصميم الصناعات الخفيفة والمنسوجات والميكانيكا.', '2026-07-16 00:25:34', '2026-07-16 00:25:34'),
(5, 2, 'en', 'Faculty of Technology', 'Technology', 'The Faculty of Technology trains engineers and technologists for chemical production, oil and gas processing, food production, agricultural product storage and processing, oil-fat technology, metrology, standardization and quality management. The faculty connects academic departments with industrial enterprises so students can reinforce theory through laboratories, production practice and graduation internships.', '[{\"title\":\"Industry Practice and Cooperation\",\"body\":\"Specialists from partner enterprises participate in classes for graduating students, assess professional knowledge, sign internship agreements and help create employment pathways for students with strong knowledge and potential.\"},{\"title\":\"Leadership\",\"body\":\"The faculty is headed by Associate Professor Rashid Tokhtayevich Adizov, PhD in Technical Sciences. The dean office includes deputy deans for academic affairs and youth affairs.\"},{\"title\":\"Academic Structure\",\"items\":[\"Oil and Gas Processing Technology\",\"Food Technology and Service\",\"Chemical Engineering\",\"Storage, Processing, and Oil-Fat Technology of Agricultural Products\",\"Oil and Gas Engineering\",\"Metrology and Standardization\"]}]', 'Faculty of Technology - BSTU', 'The Faculty of Technology trains engineers and technologists for chemical production, oil and gas processing, food production, agricultural product storage and processing, oil-fat technology, metrolog', '2026-07-16 00:25:34', '2026-07-16 00:26:05'),
(6, 2, 'uz', 'Texnologiya fakulteti', 'Texnologiya', 'Texnologiya fakulteti kimyo ishlab chiqarishi, neft va gazni qayta ishlash, oziq-ovqat ishlab chiqarish, qishloq xo‘jaligi mahsulotlarini saqlash va qayta ishlash, yog‘-moy texnologiyasi, metrologiya, standartlashtirish va sifat menejmenti yo‘nalishlari uchun muhandis va texnolog kadrlarni tayyorlaydi.', '[{\"title\":\"Ishlab chiqarish amaliyoti va hamkorlik\",\"body\":\"Hamkor korxonalar mutaxassislari bitiruvchi talabalar mashg\\u2018ulotlarida ishtirok etadi, bilimini baholaydi, amaliyot shartnomalarini rasmiylashtiradi va salohiyatli talabalar bandligiga ko\\u2018maklashadi.\"},{\"title\":\"Rahbariyat\",\"body\":\"Fakultetga texnika fanlari bo\\u2018yicha PhD, dotsent Rashid To\\u2018xtayevich Adizov rahbarlik qiladi. Dekanat tarkibida o\\u2018quv ishlari va yoshlar masalalari bo\\u2018yicha dekan o\\u2018rinbosarlari faoliyat yuritadi.\"},{\"title\":\"Akademik tuzilma\",\"items\":[\"Neft va gazni qayta ishlash texnologiyasi\",\"Oziq-ovqat texnologiyasi va servis\",\"Kimyoviy muhandislik\",\"Qishloq xo\\u2018jaligi mahsulotlarini saqlash, qayta ishlash va yog\\u2018-moy texnologiyasi\",\"Neft-gaz ishi\",\"Metrologiya va standartlashtirish\"]}]', 'Texnologiya fakulteti - BSTU', 'Texnologiya fakulteti kimyo ishlab chiqarishi, neft va gazni qayta ishlash, oziq-ovqat ishlab chiqarish, qishloq xo‘jaligi mahsulotlarini saqlash va qayta ishlash, yog‘-moy texnologiyasi, metrologiya,', '2026-07-16 00:25:34', '2026-07-16 00:26:05'),
(7, 2, 'ru', 'Факультет технологии', 'Технология', 'Факультет технологии готовит инженеров и технологов для химического производства, переработки нефти и газа, пищевой промышленности, хранения и переработки сельскохозяйственной продукции, масложировой технологии, метрологии, стандартизации и управления качеством.', '[{\"title\":\"\\u041f\\u0440\\u043e\\u0438\\u0437\\u0432\\u043e\\u0434\\u0441\\u0442\\u0432\\u0435\\u043d\\u043d\\u0430\\u044f \\u043f\\u0440\\u0430\\u043a\\u0442\\u0438\\u043a\\u0430 \\u0438 \\u0441\\u043e\\u0442\\u0440\\u0443\\u0434\\u043d\\u0438\\u0447\\u0435\\u0441\\u0442\\u0432\\u043e\",\"body\":\"\\u0421\\u043f\\u0435\\u0446\\u0438\\u0430\\u043b\\u0438\\u0441\\u0442\\u044b \\u043f\\u0440\\u0435\\u0434\\u043f\\u0440\\u0438\\u044f\\u0442\\u0438\\u0439-\\u043f\\u0430\\u0440\\u0442\\u043d\\u0451\\u0440\\u043e\\u0432 \\u0443\\u0447\\u0430\\u0441\\u0442\\u0432\\u0443\\u044e\\u0442 \\u0432 \\u0437\\u0430\\u043d\\u044f\\u0442\\u0438\\u044f\\u0445 \\u0432\\u044b\\u043f\\u0443\\u0441\\u043a\\u043d\\u044b\\u0445 \\u043a\\u0443\\u0440\\u0441\\u043e\\u0432, \\u043e\\u0446\\u0435\\u043d\\u0438\\u0432\\u0430\\u044e\\u0442 \\u043f\\u0440\\u043e\\u0444\\u0435\\u0441\\u0441\\u0438\\u043e\\u043d\\u0430\\u043b\\u044c\\u043d\\u044b\\u0435 \\u0437\\u043d\\u0430\\u043d\\u0438\\u044f \\u0441\\u0442\\u0443\\u0434\\u0435\\u043d\\u0442\\u043e\\u0432, \\u043e\\u0444\\u043e\\u0440\\u043c\\u043b\\u044f\\u044e\\u0442 \\u0434\\u043e\\u0433\\u043e\\u0432\\u043e\\u0440\\u044b \\u043f\\u0440\\u0430\\u043a\\u0442\\u0438\\u043a\\u0438 \\u0438 \\u043f\\u043e\\u043c\\u043e\\u0433\\u0430\\u044e\\u0442 \\u0441\\u043e\\u0437\\u0434\\u0430\\u0432\\u0430\\u0442\\u044c \\u0443\\u0441\\u043b\\u043e\\u0432\\u0438\\u044f \\u0434\\u043b\\u044f \\u0442\\u0440\\u0443\\u0434\\u043e\\u0443\\u0441\\u0442\\u0440\\u043e\\u0439\\u0441\\u0442\\u0432\\u0430 \\u0441\\u0438\\u043b\\u044c\\u043d\\u044b\\u0445 \\u0432\\u044b\\u043f\\u0443\\u0441\\u043a\\u043d\\u0438\\u043a\\u043e\\u0432.\"},{\"title\":\"\\u0420\\u0443\\u043a\\u043e\\u0432\\u043e\\u0434\\u0441\\u0442\\u0432\\u043e\",\"body\":\"\\u0424\\u0430\\u043a\\u0443\\u043b\\u044c\\u0442\\u0435\\u0442\\u043e\\u043c \\u0440\\u0443\\u043a\\u043e\\u0432\\u043e\\u0434\\u0438\\u0442 \\u0434\\u043e\\u0446\\u0435\\u043d\\u0442, PhD \\u043f\\u043e \\u0442\\u0435\\u0445\\u043d\\u0438\\u0447\\u0435\\u0441\\u043a\\u0438\\u043c \\u043d\\u0430\\u0443\\u043a\\u0430\\u043c \\u0420\\u0430\\u0448\\u0438\\u0434 \\u0422\\u043e\\u0445\\u0442\\u0430\\u0435\\u0432\\u0438\\u0447 \\u0410\\u0434\\u0438\\u0437\\u043e\\u0432. \\u0412 \\u0434\\u0435\\u043a\\u0430\\u043d\\u0430\\u0442\\u0435 \\u0440\\u0430\\u0431\\u043e\\u0442\\u0430\\u044e\\u0442 \\u0437\\u0430\\u043c\\u0435\\u0441\\u0442\\u0438\\u0442\\u0435\\u043b\\u0438 \\u0434\\u0435\\u043a\\u0430\\u043d\\u0430 \\u043f\\u043e \\u0443\\u0447\\u0435\\u0431\\u043d\\u043e\\u0439 \\u0440\\u0430\\u0431\\u043e\\u0442\\u0435 \\u0438 \\u043f\\u043e \\u0432\\u043e\\u043f\\u0440\\u043e\\u0441\\u0430\\u043c \\u043c\\u043e\\u043b\\u043e\\u0434\\u0451\\u0436\\u0438.\"},{\"title\":\"\\u0410\\u043a\\u0430\\u0434\\u0435\\u043c\\u0438\\u0447\\u0435\\u0441\\u043a\\u0430\\u044f \\u0441\\u0442\\u0440\\u0443\\u043a\\u0442\\u0443\\u0440\\u0430\",\"items\":[\"\\u0422\\u0435\\u0445\\u043d\\u043e\\u043b\\u043e\\u0433\\u0438\\u044f \\u043f\\u0435\\u0440\\u0435\\u0440\\u0430\\u0431\\u043e\\u0442\\u043a\\u0438 \\u043d\\u0435\\u0444\\u0442\\u0438 \\u0438 \\u0433\\u0430\\u0437\\u0430\",\"\\u041f\\u0438\\u0449\\u0435\\u0432\\u0430\\u044f \\u0442\\u0435\\u0445\\u043d\\u043e\\u043b\\u043e\\u0433\\u0438\\u044f \\u0438 \\u0441\\u0435\\u0440\\u0432\\u0438\\u0441\",\"\\u0425\\u0438\\u043c\\u0438\\u0447\\u0435\\u0441\\u043a\\u0430\\u044f \\u0438\\u043d\\u0436\\u0435\\u043d\\u0435\\u0440\\u0438\\u044f\",\"\\u0425\\u0440\\u0430\\u043d\\u0435\\u043d\\u0438\\u0435, \\u043f\\u0435\\u0440\\u0435\\u0440\\u0430\\u0431\\u043e\\u0442\\u043a\\u0430 \\u0438 \\u043c\\u0430\\u0441\\u043b\\u043e\\u0436\\u0438\\u0440\\u043e\\u0432\\u0430\\u044f