(1555, 389, 'ru', 'День памяти и почестей!', '2026-07-16 00:25:04', '2026-07-16 00:25:04'),
(1556, 389, 'ar', 'يوم الذكرى والتقدير!', '2026-07-16 00:25:04', '2026-07-16 00:25:04'),
(1557, 390, 'en', 'News', '2026-07-16 00:25:04', '2026-07-16 00:25:04'),
