INSERT INTO `video_translations` (`id`, `video_id`, `locale`, `title`, `description`, `created_at`, `updated_at`) VALUES
(1, 1, 'en', 'BSTU Graduation Ceremony - Class of 2026', 'Witness the highlights of the graduation ceremony for the class of 2026 at Bukhara State Technical University. We are proud of our graduates and wish them success in their future engineering careers.', '2026-07-16 00:26:09', '2026-07-16 00:26:09'),
(2, 1, 'uz', 'BSTU Graduation Ceremony - Class of 2026', 'Witness the highlights of the graduation ceremony for the class of 2026 at Bukhara State Technical University. We are proud of our graduates and wish them success in their future engineering careers.', '2026-07-16 00:26:09', '2026-07-16 00:26:09'),
(3, 1, 'ru', 'Выпускная церемония БГТУ - Выпуск 2026 года', 'Посмотрите основные моменты выпускной церемонии 2026 года в Бухарском государственном техническом университете. Мы гордимся нашими выпускниками и желаем им успехов в будущей инженерной карьере.', '2026-07-16 00:26:09', '2026-07-16 00:26:09'),
(4, 1, 'ar', 'حفل تخرج جامعة بخارى الحكومية التقنية - دفعة 2026', 'شاهدوا أبرز لقطات حفل التخرج البهيج لدفعة عام 2026 في جامعة بخارى الحكومية التقنية. فخورون بطلابنا الخريجين ونتمنى لهم كامل التوفيق والنجاح في مسيرتهم الهندسية الواعدة.', '2026-07-16 00:26:09', '2026-07-16 00:26:09'),
(5, 2, 'en', 'Academic and Practical Training Highlights', 'A short overview of classroom learning, workshops, and hands-on training activities at BSTU.', '2026-07-16 00:26:09', '2026-07-16 00:26:09'),
(6, 2, 'uz', '#jarayon', 'Highlights from academic and practical processes', '2026-07-16 00:26:09', '2026-07-16 00:26:09'),
(7, 2, 'ru', 'Учебный и практический процесс', 'Краткий обзор учебных занятий, лабораторных работ и практической подготовки студентов БГТУ.', '2026-07-16 00:26:09', '2026-07-16 00:26:09'),
(8, 2, 'ar', 'لمحات من العملية التعليمية والتطبيقية', 'عرض موجز لأنشطة الدراسة النظرية والتدريب العملي داخل الجامعة.', '2026-07-16 00:26:09', '2026-07-16 00:26:09'),
(9, 3, 'en', 'Engineering Month Highlights', 'Key moments from Engineering Month, featuring student participation, projects, and innovation events.', '2026-07-16 00:26:09', '2026-07-16 00:26:09'),
(10, 3, 'uz', '#Engineering_Month', 'Events organized during the Engineering Month', '2026-07-16 00:26:09', '2026-07-16 00:26:09'),
(11, 3, 'ru', 'Месяц инженерии: ключевые моменты', 'Самые яркие события Месяца инженерии: проекты, конкурсы и академические активности.', '2026-07-16 00:26:09', '2026-07-16 00:26:09'),
(12, 3, 'ar', 'أبرز فعاليات شهر الهندسة', 'ملخص لأهم الفعاليات والمشروعات الطلابية التي نُظمت خلال شهر الهندسة.', '2026-07-16 00:26:09', '2026-07-16 00:26:09'),
(13, 4, 'en', 'Engineering Month at BSTU', 'An inside look at academic and technical activities organized during Engineering Month at BSTU.', '2026-07-16 00:26:09', '2026-07-16 00:26:09'),
(14, 4, 'uz', '#Muhandislik_oyligi', 'Engineering Month at Bukhara State Technical University', '2026-07-16 00:26:09', '2026-07-16 00:26:09'),
(15, 4, 'ru', 'Месяц инженерии в БГТУ', 'Обзор мероприятий и инженерных инициатив, реализованных в рамках тематического месяца.', '2026-07-16 00:26:09', '2026-07-16 00:26:09'),
(16, 4, 'ar', 'شهر الهندسة في جامعة بخارى التقنية', 'نظرة على الأنشطة العلمية والتقنية التي شهدها الحرم الجامعي ضمن شهر الهندسة.', '2026-07-16 00:26:09', '2026-07-16 00:26:09'),
(17, 5, 'en', 'Inside BSTU Laboratories', 'Snapshots from educational and scientific laboratories where students apply theory in practice.', '2026-07-16 00:26:09', '2026-07-16 00:26:09'),
(18, 5, 'uz', '#jarayon', 'Process snapshots from educational and scientific laboratories', '2026-07-16 00:26:09', '2026-07-16 00:26:09'),
(19, 5, 'ru', 'Лаборатории БГТУ изнутри', 'Кадры из учебных и научных лабораторий, где студенты закрепляют знания на практике.', '2026-07-16 00:26:09', '2026-07-16 00:26:09'),
(20, 5, 'ar', 'من داخل المختبرات العلمية', 'لقطات من المختبرات التعليمية والبحثية حيث يطبق الطلاب المعرفة عملياً.', '2026-07-16 00:26:09', '2026-07-16 00:26:09'),
